function numeric(v, fields){const o={};for(const [k,label,u,d] of fields){let z=v && Object.prototype.hasOwnProperty.call(v,k)?v[k]:d;if(z===null||typeof z==='boolean'||(typeof z==='string'&&z.trim()===''))throw Error(label+' must be finite');z=Number(z);if(!Number.isFinite(z))throw Error(label+' must be finite');o[k]=z;}return o;}
